import { View, Text, FlatList, StyleSheet } from "react-native";
import { registerRootComponent } from "expo";

const PRODUCTS = [
  { id: "p1", name: "Чихэвч" },
  { id: "p2", name: "Гар цаг" },
  { id: "p3", name: "Нарны шил" },
  { id: "p4", name: "Цүнх" },
  { id: "p5", name: "Гутал" },
  { id: "p6", name: "Ном" },
];

function App() {
  // энд бичнэ үү: FlatList-д numColumns={2} нэмж 2 баганат тор болго
  return (
    <FlatList
      style={styles.list}
      data={PRODUCTS}
      keyExtractor={(item) => item.id}
      renderItem={({ item }) => (
        <View testID="tile" style={styles.tile}>
          <Text style={styles.name}>{item.name}</Text>
        </View>
      )}
    />
  );
}

const styles = StyleSheet.create({
  list: { flex: 1, backgroundColor: "#f8fafc", padding: 8 },
  tile: { flex: 1, margin: 8, height: 90, backgroundColor: "#fff", borderRadius: 12, alignItems: "center", justifyContent: "center", elevation: 2 },
  name: { fontSize: 15, fontWeight: "600" },
});

registerRootComponent(App);

